import "core-js/modules/es6.function.name";
import { citypeList, getCiInheritList, ciSave, ciDetail } from "@/api/system/ciModel";
import iconList from "./iconList";
export default {
  components: {
    iconList: iconList
  },
  props: ["isShow", "ciId", "showType"],
  data: function data() {
    return {
      submitForm: {
        icon: 'tsfont-ci',
        isVirtual: 0,
        isMenu: 0,
        isAbstract: 0
      },
      rules: {
        typeId: [{
          required: true,
          message: '模型层级不能为空',
          trigger: 'blur'
        }],
        name: [{
          required: true,
          message: '唯一标识不能为空',
          trigger: 'blur'
        }],
        label: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }]
      },
      ciTypeList: [],
      ciInheritList: [],
      // 弹窗
      showIcon: false
    };
  },
  mounted: function mounted() {
    this.getDicts();
    this.getDetail();
  },
  methods: {
    // 获得详情
    getDetail: function getDetail() {
      var _this = this;
      if (this.showType == '修改') {
        this.pageLoading = true;
        ciDetail({
          id: this.ciId,
          needAction: true
        }).then(function (res) {
          _this.submitForm = res.Return;
          _this.pageLoading = false;
        }).catch(function () {
          _this.pageLoading = false;
        });
      }
    },
    // 字典值
    getDicts: function getDicts() {
      var _this2 = this;
      // 模型层级
      citypeList().then(function (res) {
        _this2.ciTypeList = res.Return;
      });
      // 继承列表
      getCiInheritList({
        isAbstract: 1,
        isVirtual: 0
      }).then(function (res) {
        _this2.ciInheritList = res.Return;
      });
    },
    // 获得层级名称
    changeCitype: function changeCitype(val) {
      for (var i = 0; i < this.ciTypeList.length; i++) {
        var item = this.ciTypeList[i];
        if (item.id === val) this.submitForm.typeName = item.name;
      }
    },
    // 获得继承名称
    changeParentCi: function changeParentCi(val) {
      for (var i = 0; i < this.ciInheritList.length; i++) {
        var item = this.ciInheritList[i];
        if (item.value === val) {
          var indexStart = item.text.indexOf('(');
          var indexEnd = item.text.indexOf(')');
          if (indexStart !== -1 && indexEnd !== -1) {
            this.submitForm.parentCiLabel = item.text.substring(0, indexStart);
            this.submitForm.parentCiName = item.text.substring(indexStart + 1, indexEnd);
          } else {
            this.submitForm.parentCiLabel = "";
            this.submitForm.parentCiName = "";
          }
          break;
        }
      }
    },
    save: function save() {
      var _this3 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          _this3.saveLoading = true;
          ciSave(_this3.submitForm).then(function (res) {
            _this3.$message({
              type: 'success',
              message: '保存成功！'
            });
            _this3.$emit('saveCi');
            _this3.saveLoading = false;
          }).catch(function () {
            _this3.saveLoading = false;
          });
        }
      });
    },
    selectIcon: function selectIcon() {
      this.showIcon = true;
    },
    setIcon: function setIcon(val) {
      this.showIcon = false;
      this.submitForm.icon = val;
    }
  }
};
